// leak: listener keeps `controller` (and everything it closes over) alive forever
function attach(controller) {
  window.addEventListener('resize', () => controller.onResize());
}

// fixed: keep a reference so it can be removed later
function attach(controller) {
  const handler = () => controller.onResize();
  window.addEventListener('resize', handler);
  return () => window.removeEventListener('resize', handler);
}
